use std::any::Any;
use std::fmt::Debug;

trait Shape: Debug {
    fn area(&self) -> f64;
    fn as_any(&self) -> &dyn Any;
}

#[derive(Debug)]
struct Circle(f64);
#[derive(Debug)]
struct Square(f64);

impl Shape for Circle {
    fn area(&self) -> f64 {
        3.14159 * self.0 * self.0
    }
    fn as_any(&self) -> &dyn Any {
        self
    }
}

impl Shape for Square {
    fn area(&self) -> f64 {
        self.0 * self.0
    }
    fn as_any(&self) -> &dyn Any {
        self
    }
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![Box::new(Circle(1.0)), Box::new(Square(2.0))];
    let total: f64 = shapes.iter().map(|s| s.area()).sum();
    println!("{shapes:?} total area {total:.2}");

    for s in &shapes {
        if let Some(sq) = s.as_any().downcast_ref::<Square>() {
            println!("found a square with side {}", sq.0);
        }
    }
}

